package org.cttelsamicsterrassa.data.core.application.player.find;
import org.albertsanso.commons.query.*; import org.cttelsamicsterrassa.data.core.domain.player.model.PlayerSeason; import org.cttelsamicsterrassa.data.core.domain.player.repository.PlayerSeasonRepository; import javax.inject.*;
@Named public class FindPlayerSeasonByLicenseAndSeasonQueryHandler extends DomainQueryHandler<FindPlayerSeasonByLicenseAndSeasonQuery,PlayerSeason>{private final PlayerSeasonRepository r;@Inject public FindPlayerSeasonByLicenseAndSeasonQueryHandler(PlayerSeasonRepository r){this.r=r;}public DomainQueryResponse<PlayerSeason> handle(FindPlayerSeasonByLicenseAndSeasonQuery q){return r.findPlayerSeasonByLicenseAndSeason(q.getSource(),q.getLicense(),q.getSeason()).map(DomainQueryResponse::sucessResponse).orElseGet(()->DomainQueryResponse.failResponse(null));}}
